using System.Globalization;using System.Text;using ClosedXML.Excel;using Microsoft.EntityFrameworkCore;using UAF.API.Authorization;using UAF.Domain.Entities;using UAF.Infrastructure.Persistence;
namespace UAF.API.Endpoints;
public static class StudentDataExchangeEndpoints{
 private static readonly string[] Headers=["RegistrationNumber","FullName","Email","EnrollmentDate","PhoneNumber"];
 public static IEndpointRouteBuilder MapStudentDataExchangeEndpoints(this IEndpointRouteBuilder app){
 var group=app.MapGroup("/api/v1/data-exchange/students").WithTags("Student Import and Export");
 group.MapGet("/",async(string?format,Guid?programId,UafDbContext db,CancellationToken ct)=>{var q=db.Students.AsNoTracking().AsQueryable();if(programId.HasValue)q=q.Where(x=>x.AcademicProgramId==programId.Value);var rows=await q.OrderBy(x=>x.RegistrationNumber).Select(x=>new{x.RegistrationNumber,x.FullName,x.Email,x.EnrollmentDate,x.PhoneNumber}).ToListAsync(ct);var fmt=(format??"csv").ToLowerInvariant();if(fmt=="csv"){var sb=new StringBuilder();sb.AppendLine(string.Join(",",Headers));foreach(var x in rows)sb.AppendLine(string.Join(",",new[]{x.RegistrationNumber,x.FullName,x.Email,x.EnrollmentDate.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),x.PhoneNumber??""}.Select(EscapeCsv)));return Results.File(Encoding.UTF8.GetBytes(sb.ToString()),"text/csv; charset=utf-8","students.csv");}if(fmt=="xlsx"){using var book=new XLWorkbook();var sheet=book.Worksheets.Add("Students");for(var i=0;i<Headers.Length;i++)sheet.Cell(1,i+1).Value=Headers[i];for(var i=0;i<rows.Count;i++){var x=rows[i];sheet.Cell(i+2,1).Value=x.RegistrationNumber;sheet.Cell(i+2,2).Value=x.FullName;sheet.Cell(i+2,3).Value=x.Email;sheet.Cell(i+2,4).Value=x.EnrollmentDate.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);sheet.Cell(i+2,5).Value=x.PhoneNumber??"";}sheet.RangeUsed()?.SetAutoFilter();sheet.Columns().AdjustToContents();using var stream=new MemoryStream();book.SaveAs(stream);return Results.File(stream.ToArray(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","students.xlsx");}return Results.BadRequest(new{error="format must be csv or xlsx."});}).RequireAuthorization("Permission:students.read").WithName("ExportStudents");
 group.MapPost("/import",async(IFormFile file,Guid academicProgramId,UafDbContext db,CancellationToken ct)=>{if(file is null||file.Length==0)return Results.BadRequest(new{error="Upload a non-empty CSV or XLSX file."});if(file.Length>10*1024*1024)return Results.BadRequest(new{error="Import file cannot exceed 10 MB."});if(!await db.AcademicPrograms.AnyAsync(x=>x.Id==academicProgramId,ct))return Results.NotFound(new{error="Academic program not found."});var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(ext is not ".csv" and not ".xlsx")return Results.BadRequest(new{error="Only .csv and .xlsx files are supported."});List<string[]> rows;try{await using var input=file.OpenReadStream();rows=ext==".csv"?ParseCsv(input):ParseXlsx(input);}catch(Exception ex)when(ex is not OperationCanceledException){return Results.BadRequest(new{error="The import file could not be read.",detail=ex.Message});}if(rows.Count<2)return Results.BadRequest(new{error="The file must contain a header and at least one student row."});var header=rows[0].Select(x=>x.Trim()).ToArray();var indexes=Headers.Select(h=>Array.FindIndex(header,x=>string.Equals(x,h,StringComparison.OrdinalIgnoreCase))).ToArray();if(indexes.Any(x=>x<0))return Results.BadRequest(new{error="Required columns: "+string.Join(", ",Headers)});var errors=new List<string>();var students=new List<Student>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);for(var i=1;i<rows.Count;i++){var row=rows[i];if(row.All(string.IsNullOrWhiteSpace))continue;string Get(int index)=>indexes[index]<row.Length?row[index].Trim():string.Empty;var reg=Get(0);var name=Get(1);var email=Get(2);var dateText=Get(3);var phone=Get(4);if(!seen.Add(reg)){errors.Add($"Row {i+1}: duplicate registration number '{reg}' in file.");continue;}if(!DateOnly.TryParse(dateText,CultureInfo.InvariantCulture,DateTimeStyles.None,out var enrollmentDate)){errors.Add($"Row {i+1}: EnrollmentDate must be a valid date (yyyy-MM-dd).");continue;}try{students.Add(new Student(reg,name,email,academicProgramId,enrollmentDate,phone));}catch(ArgumentException ex){errors.Add($"Row {i+1}: {ex.Message}");}}if(errors.Count>0)return Results.BadRequest(new{imported=0,errors});var registrations=students.Select(x=>x.RegistrationNumber).ToArray();var existing=await db.Students.Where(x=>registrations.Contains(x.RegistrationNumber)).Select(x=>x.RegistrationNumber).ToListAsync(ct);if(existing.Count>0)return Results.Conflict(new{imported=0,errors=existing.Select(x=>$"Registration number '{x}' already exists.").ToArray()});db.Students.AddRange(students);await db.SaveChangesAsync(ct);return Results.Ok(new{imported=students.Count,errors=Array.Empty<string>()});}).RequireAuthorization(AuthorizationPolicies.StudentManagement).DisableAntiforgery().WithName("ImportStudents");
 return app;
 }
 private static string EscapeCsv(string value)=>"\""+value.Replace("\"","\"\"")+"\"";
 private static List<string[]> ParseXlsx(Stream stream){using var book=new XLWorkbook(stream);var sheet=book.Worksheets.First();return sheet.RowsUsed().Select(r=>r.Cells(1,Math.Max(r.LastCellUsed()?.Address.ColumnNumber??1,1)).Select(c=>c.GetString()).ToArray()).ToList();}
 private static List<string[]> ParseCsv(Stream stream){using var reader=new StreamReader(stream,Encoding.UTF8,true,1024,true);var result=new List<string[]>();var row=new List<string>();var field=new StringBuilder();var quoted=false;while(true){var value=reader.Read();if(value<0)break;var ch=(char)value;if(quoted){if(ch=='"'){if(reader.Peek()=='"'){reader.Read();field.Append('"');}else quoted=false;}else field.Append(ch);continue;}if(ch=='"'&&field.Length==0){quoted=true;continue;}if(ch==','){row.Add(field.ToString());field.Clear();continue;}if(ch=='\r')continue;if(ch=='\n'){row.Add(field.ToString());field.Clear();result.Add(row.ToArray());row.Clear();continue;}field.Append(ch);}if(quoted)throw new InvalidDataException("CSV contains an unterminated quoted field.");if(field.Length>0||row.Count>0){row.Add(field.ToString());result.Add(row.ToArray());}return result;}
}
